import{_ as s,o as e,c as n,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"AI Coding 工作流","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/coding/cursor-workflow.md","filePath":"ai/dev/coding/cursor-workflow.md"}'),l={name:"ai/dev/coding/cursor-workflow.md"};function r(t,a,p,d,h,o){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="ai-coding-工作流" tabindex="-1">AI Coding 工作流 <a class="header-anchor" href="#ai-coding-工作流" aria-label="Permalink to “AI Coding 工作流”">​</a></h1><blockquote><p>我如何把 AI 纳入真实的软件开发闭环。不是 Cursor 按钮说明书。</p></blockquote><h3 id="什么时候用" tabindex="-1">什么时候用？ <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用？”">​</a></h3><p>当你需要从需求开始完整使用 AI Coding，而不是单独让 AI 写一段代码时。</p><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>形成可重复的总流程（不必每次从零重读）：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求 → 拆解 → Context → AI 实现 → 人工判断</span></span>
<span class="line"><span> → Review → Test → Debug → Refactor → Delivery</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>核心原则：</p><blockquote><p><strong>AI 可以提高代码生产速度，但不能替代开发者对需求、架构、质量和最终结果负责。</strong></p></blockquote><hr><h2 id="完整闭环-10-步" tabindex="-1">完整闭环（10 步） <a class="header-anchor" href="#完整闭环-10-步" aria-label="Permalink to “完整闭环（10 步）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 明确需求</span></span>
<span class="line"><span>2. 拆解任务</span></span>
<span class="line"><span>3. 准备上下文</span></span>
<span class="line"><span>4. 与 AI 协作实现</span></span>
<span class="line"><span>5. 人工架构判断</span></span>
<span class="line"><span>6. Code Review</span></span>
<span class="line"><span>7. 测试</span></span>
<span class="line"><span>8. Debug</span></span>
<span class="line"><span>9. 重构</span></span>
<span class="line"><span>10. 交付与复盘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><hr><h2 id="_1-明确需求" tabindex="-1">1. 明确需求 <a class="header-anchor" href="#_1-明确需求" aria-label="Permalink to “1. 明确需求”">​</a></h2><p>动手前先写清三件事：</p><ul><li><strong>要解决什么问题</strong>（用户/业务结果）</li><li><strong>验收标准是什么</strong>（怎样算做完）</li><li><strong>边界在哪里</strong>（不改什么、不做什么）</li></ul><p>AI 最容易「自作主张扩 scope」。需求与边界不清时，生成再快也是在制造返工。</p><p>人负责：需求理解与验收定义。<br> AI 不负责：替你决定「业务上该不该做」。</p><hr><h2 id="_2-拆解任务" tabindex="-1">2. 拆解任务 <a class="header-anchor" href="#_2-拆解任务" aria-label="Permalink to “2. 拆解任务”">​</a></h2><p>把大需求拆成可验证的小步骤，例如：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>读懂现有调用链</span></span>
<span class="line"><span> → 改一个接口 / 一张表 / 一个前端页</span></span>
<span class="line"><span> → 补测试或手工验收路径</span></span>
<span class="line"><span> → 再处理下一刀</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>原则：</p><ul><li>一次只推进一类改动</li><li>每步有可观察的结果（编译过、用例过、页面能点）</li><li>先最小闭环，再谈优化与重构</li></ul><p>拆解是工程能力，不是 Prompt 技巧。拆得清楚，AI 才稳。</p><hr><h2 id="_3-准备上下文" tabindex="-1">3. 准备上下文 <a class="header-anchor" href="#_3-准备上下文" aria-label="Permalink to “3. 准备上下文”">​</a></h2><p>AI 只看得到你给它的材料。优先准备：</p><ul><li>相关代码与调用链（不要只丢孤立片段）</li><li>Git Diff / 当前改动范围</li><li>接口定义、表结构、错误日志（若涉及）</li><li>业务规则与约束（「不能改公共 API」「必须兼容旧数据」）</li><li>已有测试或验收步骤</li></ul><p>上下文越具体，输出越像「在这个项目里写代码」，而不是「通用示例」。</p><p>通用 Prompt 结构见 <a href="/my-vitepress-site/ai/dev/basics/prompt-engineering.html">Prompt 怎么写才像工程</a>。</p><hr><h2 id="_4-与-ai-协作实现" tabindex="-1">4. 与 AI 协作实现 <a class="header-anchor" href="#_4-与-ai-协作实现" aria-label="Permalink to “4. 与 AI 协作实现”">​</a></h2><p>推荐节奏：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>先让 AI 分析 / 给方案</span></span>
<span class="line"><span> → 人确认方案与边界</span></span>
<span class="line"><span> → 再让 AI 按确认项改代码</span></span>
<span class="line"><span> → 人看 Diff，跑起来验证</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>尽量避免：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>一句话「帮我实现某某」</span></span>
<span class="line"><span> → AI 直接大改几十个文件</span></span>
<span class="line"><span> → 引入无关重构与新问题</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>人负责：范围、风格、是否允许重构。<br> AI 负责：在约束内提高实现速度。</p><hr><h2 id="_5-人工架构判断" tabindex="-1">5. 人工架构判断 <a class="header-anchor" href="#_5-人工架构判断" aria-label="Permalink to “5. 人工架构判断”">​</a></h2><p>AI 生成之后，先问自己，而不是先问「还能不能再生成一点」：</p><ul><li>模块边界是否被破坏？</li><li>是否引入不必要的抽象或依赖？</li><li>是否符合现有分层（Controller / Service / 仓储等）？</li><li>扩展点是否合理，还是在堆特例？</li><li>有没有为了「看起来高级」而过度设计？</li></ul><p>这一步<strong>不能外包给模型</strong>。架构取舍依赖项目上下文与长期维护成本，属于开发者职责。</p><hr><h2 id="_6-code-review" tabindex="-1">6. Code Review <a class="header-anchor" href="#_6-code-review" aria-label="Permalink to “6. Code Review”">​</a></h2><p>AI 适合做第一轮广泛扫描；人做最终判断。</p><p>重点看：</p><ul><li>本次修改是否引入缺陷</li><li>边界条件、空值、异常路径</li><li>权限、数据一致性、并发（若相关）</li><li>是否误报、是否漏报</li></ul><p>工作方式与可复制 Prompt 见 <a href="/my-vitepress-site/ai/dev/coding/ai-code-review.html">用 AI 做 Code Review</a>。</p><p>记住：</p><blockquote><p>AI 发现的问题不一定是真的；AI 没发现也不代表没有问题。</p></blockquote><hr><h2 id="_7-测试" tabindex="-1">7. 测试 <a class="header-anchor" href="#_7-测试" aria-label="Permalink to “7. 测试”">​</a></h2><p>能自动化的尽量自动化；没有现成测试时，至少固定一条人工验收路径。</p><p>优先验证：</p><ul><li>主路径是否按验收标准通过</li><li>关键边界与失败路径</li><li>回归：改动是否影响相邻功能</li></ul><p>AI 可以帮写测试草稿，但：</p><ul><li>测什么、覆盖哪条业务规则 → 人定</li><li>测试是否真能抓住风险 → 人判</li></ul><p>「测试绿了」不等于「业务对了」，尤其在 AI 大量生成代码时。</p><hr><h2 id="_8-debug" tabindex="-1">8. Debug <a class="header-anchor" href="#_8-debug" aria-label="Permalink to “8. Debug”">​</a></h2><p>出问题时，仍按工程方式定位：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>复现</span></span>
<span class="line"><span> → 缩小范围</span></span>
<span class="line"><span> → 看日志 / Diff / 调用链</span></span>
<span class="line"><span> → 形成假设</span></span>
<span class="line"><span> → 最小验证</span></span>
<span class="line"><span> → 再改</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>可以让 AI 辅助读栈、猜可疑点，但不要跳过复现与缩小范围。<br> 「再让 AI 整段重写」往往比「定点修」引入更多未知。</p><p>（<code>fix-one-bug</code> 等专项页有材料后再挂进来；本页先把 Debug 放进闭环。）</p><hr><h2 id="_9-重构" tabindex="-1">9. 重构 <a class="header-anchor" href="#_9-重构" aria-label="Permalink to “9. 重构”">​</a></h2><p>重构单独成步，不要和功能交付缠在一起。</p><ul><li>功能未验收前：禁止顺手大重构</li><li>验收后：只改结构、行为不变，并有测试或验收托底</li><li>每次重构目标单一（命名、抽取、去重……）</li></ul><p>AI 很擅长「看起来更优雅」的重写；人要负责判断值不值、风险大不大。</p><hr><h2 id="_10-交付与复盘" tabindex="-1">10. 交付与复盘 <a class="header-anchor" href="#_10-交付与复盘" aria-label="Permalink to “10. 交付与复盘”">​</a></h2><p>交付前至少确认：</p><ul><li>Diff 范围符合预期，无无关文件</li><li>验收标准已勾完</li><li>必要说明（PR / 变更说明）写清「改了什么、为什么、怎么验」</li></ul><p>复盘只记对下次有用的：</p><ul><li>哪类上下文一给就稳</li><li>哪类任务不适合一次性丢给 AI</li><li>哪次误报 / 漏报值得写进 Review 习惯</li></ul><p>复盘是把「用过 AI」变成「可重复的工程方法」。</p><hr><h2 id="人机分工-面试可直接说" tabindex="-1">人机分工（面试可直接说） <a class="header-anchor" href="#人机分工-面试可直接说" aria-label="Permalink to “人机分工（面试可直接说）”">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>更偏谁</th></tr></thead><tbody><tr><td>需求与验收</td><td>人</td></tr><tr><td>任务拆解</td><td>人（可让 AI 帮忙列草案）</td></tr><tr><td>上下文准备</td><td>人为主</td></tr><tr><td>代码实现草稿</td><td>AI + 人约束</td></tr><tr><td>架构判断</td><td>人</td></tr><tr><td>Code Review</td><td>AI 初扫 + 人终审</td></tr><tr><td>测试策略</td><td>人；用例草稿可 AI</td></tr><tr><td>Debug 结论</td><td>人</td></tr><tr><td>是否重构、重构范围</td><td>人</td></tr><tr><td>最终交付责任</td><td>人</td></tr></tbody></table><hr><h2 id="和「会用-cursor」的差别" tabindex="-1">和「会用 Cursor」的差别 <a class="header-anchor" href="#和「会用-cursor」的差别" aria-label="Permalink to “和「会用 Cursor」的差别”">​</a></h2><table tabindex="0"><thead><tr><th>会用工具</th><th>AI Coding 工作流</th></tr></thead><tbody><tr><td>会提问、会补全</td><td>有固定闭环与验收</td></tr><tr><td>生成得多</td><td>改得准、回得了滚</td></tr><tr><td>依赖某一款 IDE</td><td>方法可迁移到别的工具</td></tr><tr><td>出问题再问 AI</td><td>先复现、再定点、再让 AI 辅助</td></tr></tbody></table><p>实战展开见：</p><ul><li><a href="/my-vitepress-site/ai/ai-programming/cursor-legacy-project.html">Cursor 老项目实战</a></li><li><a href="/my-vitepress-site/ai/ai-programming/cursor-new-project.html">Cursor 新项目实战</a></li><li><a href="/my-vitepress-site/ai/dev/coding/">AI Coding 概览</a></li></ul><hr><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to “我的判断”">​</a></h2><p>工作流的价值不在步骤名称，而在强制一件事：</p><blockquote><p><strong>每一步都知道谁拍板、用什么验收、AI 准许动到哪里。</strong></p></blockquote><p>做到这一点，AI 才是工程放大器；做不到，只是更快地制造技术债。</p>`,90)])])}const u=s(l,[["render",r]]);export{b as __pageData,u as default};
